import sys, json; sys.path.insert(0,'/workspace/project')
import main as impl
import refexpr

def evaluate(defs):
    doc = {'seed':'s','definitions':defs,'timeout_ms':10,
           'cases':[{'name':'a','frames':[{'Type':'data','data_to_transfered':'{{X}}','End_Stream':True}],
                     'expect':{'method':'GET','target':'/','host':'h'}}],
           'events':[],'channels':[]}
    try:
        out = impl.run(doc)
    except Exception:
        return None
    if 'error' in out:
        return None
    return out['cases'][0]['sent']

def value(defs):
    env = {}
    try:
        for name, expr in defs:
            body = refexpr.parse(expr)
            v = refexpr.ev(body, env)
            if isinstance(v, int): return None
            env[name] = v
    except refexpr.Bad:
        return None
    return env[defs[-1][0]]

bases = ["b'abc'", "b'a'*7", "(b'ab'+b'cd')*3", "b'x'", "b''", "(b'abc'*2)[1:4]", "b'q'*1000"]
bad = 0
for base in bases:
    v = value([['X', base]])
    if v is None: continue
    n = len(v)
    for lo in range(0, n+2):
        for hi in range(lo, n+2):
            expr = "(X)[%d:%d]" % (lo, hi)
            got = evaluate([['X', base], ['Y', expr]])
            want = value([['X', base], ['Y', expr]])
            if want is None:
                if got is not None:
                    print('EXPECTED ERR', base, expr); bad += 1
                continue
            if got is None:
                print('UNEXPECTED ERR', base, expr); bad += 1; continue
            data = want
            receipt = (0).to_bytes(8,'big')+(0).to_bytes(4,'big')+b'D'+len(data).to_bytes(8,'big')+data+b'\x01'
            if got != refexpr.fp(receipt):
                print('MISMATCH', base, expr, got, refexpr.fp(receipt)); bad += 1
    if bad > 5: break
print('done, failures:', bad)
